class Solution {
    public int reachNumber(int target) {
        long t = Math.abs((long) target);
        long hi = 1;
        while (triangular(hi) < t) {
            hi *= 2;
        }
        long lo = 0;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (triangular(mid) >= t) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        long step = lo;
        long sum = triangular(step);
        while (((sum - t) & 1L) == 1L) {
            step++;
            sum += step;
        }
        return (int) step;
    }

    private long triangular(long step) {
        return step * (step + 1) / 2;
    }
}

