        long t = Math.abs((long) target);
        long step = (long) Math.ceil((Math.sqrt(8.0 * t + 1.0) - 1.0) / 2.0);
        long sum = step * (step + 1) / 2;
        while (sum < t) {
            step++;
            sum += step;
        }
        while (((sum - t) & 1L) == 1L) {
            step++;
            sum += step;
        }
        return (int) step;
    }
}

class Solution {
    public int reachNumber(int target) {
        long t = Math.abs((long) target);
        long sum = 0;
        int step = 0;
        while (sum < t) {
            step++;
            sum += step;
        }
        long overshoot = sum - t;
        if ((overshoot & 1L) == 0L) {
            return step;
        }
        return ((step + 1) & 1) == 1 ? step + 1 : step + 2;
    }
}

class Solution {
    public int reachNumber(int target) {
        long t = Math.abs((long) target);
        long lo = 0, hi = 100000;
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (mid * (mid + 1) / 2 >= t) {
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        long step = lo;
        while (triangularParity(step) != (t & 1L)) {
            step++;
        }
        return (int) step;
    }

    private long triangularParity(long step) {
        long residue = step & 3L;
        return (residue == 1L || residue == 2L) ? 1L : 0L;
    }
}
